import itertools, sys
sys.path.insert(0,'.')
from reduce import reduce

def ss_witness(inst):
    nums=inst["numbers"]; t=inst["target"]
    # DP storing predecessor
    reach={0:None}
    for i,a in enumerate(nums):
        new={}
        for s in reach:
            v=s+a
            if v<=t and v not in reach and v not in new:
                new[v]=i
        for v,i in new.items():
            reach[v]=i
    if t not in reach: return None
    # reconstruct
    chosen=[]; cur=t
    # simple backtrack using stored index won't work directly; redo
    return reach

m=3
clauses=[]
for combo in itertools.product([1,-1],repeat=3):
    clauses.append([combo[0]*1, combo[1]*2, combo[2]*3])
inst={"num_vars":m,"clauses":clauses}
r=reduce(inst)
# find subset via recursion
nums=r["numbers"]; t=r["target"]
found=[]
def rec(i,s):
    if s==t: return True
    if i==len(nums) or s>t: return False
    if rec(i+1,s+nums[i]):
        found.append(i); return True
    return rec(i+1,s)
print("found subset:", rec(0,0))
print("indices", sorted(found))
print("sum check", sum(nums[i] for i in found), "target", t)
# print which are slacks
print("numbers:", nums)
